-- Rodos Liberta: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-1k9tn50','rodos-official-1k9tn53','rodos-official-1k9tn52','rodos-official-1k9tn4x','rodos-official-1k9tn4w','rodos-official-1kwd7ts','rodos-official-o5lwt8')) <> 7 then raise exception 'Не знайдено всі моделі Rodos Liberta для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-1k9tn50';
delete from public.product_variants where product_slug = 'rodos-official-1k9tn50';
delete from public.product_media where product_slug = 'rodos-official-1k9tn50' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1k9tn53';
delete from public.product_variants where product_slug = 'rodos-official-1k9tn53';
delete from public.product_media where product_slug = 'rodos-official-1k9tn53' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1k9tn52';
delete from public.product_variants where product_slug = 'rodos-official-1k9tn52';
delete from public.product_media where product_slug = 'rodos-official-1k9tn52' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1k9tn4x';
delete from public.product_variants where product_slug = 'rodos-official-1k9tn4x';
delete from public.product_media where product_slug = 'rodos-official-1k9tn4x' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1k9tn4w';
delete from public.product_variants where product_slug = 'rodos-official-1k9tn4w';
delete from public.product_media where product_slug = 'rodos-official-1k9tn4w' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1kwd7ts';
delete from public.product_variants where product_slug = 'rodos-official-1kwd7ts';
delete from public.product_media where product_slug = 'rodos-official-1kwd7ts' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-o5lwt8';
delete from public.product_variants where product_slug = 'rodos-official-o5lwt8';
delete from public.product_media where product_slug = 'rodos-official-o5lwt8' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-1k9tn50','rodos-official-1k9tn53','rodos-official-1k9tn52','rodos-official-1k9tn4x','rodos-official-1k9tn4w','rodos-official-1kwd7ts','rodos-official-o5lwt8') group by product_slug order by product_slug;